import type { IncomingMessage, ServerResponse } from "node:http";

type JsonResponse = Record<string, string | number>;
export type Logger = (message: string) => void;

function sendJson(
  response: ServerResponse,
  statusCode: number,
  body: JsonResponse,
): void {
  const payload = JSON.stringify(body);

  response.writeHead(statusCode, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(payload),
  });
  response.end(payload);
}

export function createRequestHandler(logger: Logger = console.log) {
  let pongCount = 0;

  return function requestHandler(
    request: IncomingMessage,
    response: ServerResponse,
  ): void {
    const requestUrl = new URL(
      request.url ?? "/",
      `http://${request.headers.host ?? "localhost"}`,
    );

    if (requestUrl.pathname === "/ping") {
      if (request.method !== "GET") {
        response.setHeader("Allow", "GET");
        sendJson(response, 405, { error: "Method Not Allowed" });
        return;
      }

      pongCount += 1;
      logger(`ping received; pong count=${pongCount}`);
      sendJson(response, 200, { message: "pong", count: pongCount });
      return;
    }

    sendJson(response, 404, { error: "Not Found" });
  };
}

export const requestHandler = createRequestHandler();
package main

import (
	"encoding/json"
	"net/http"
	"strconv"
)

const jsonContentType = "application/json; charset=utf-8"

type messageResponse struct {
	Message string `json:"message"`
}

type errorResponse struct {
	Error string `json:"error"`
}

// newHandler returns the HTTP handler for the ping-pong API.
func newHandler() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := "/"
		if r.URL != nil {
			// EscapedPath keeps encoded paths distinct from their decoded form,
			// matching the TypeScript implementation's pathname comparison.
			path = r.URL.EscapedPath()
		}

		if path != "/ping" {
			writeJSON(w, http.StatusNotFound, errorResponse{Error: "Not Found"})
			return
		}

		if r.Method != http.MethodGet {
			w.Header().Set("Allow", http.MethodGet)
			writeJSON(w, http.StatusMethodNotAllowed, errorResponse{Error: "Method Not Allowed"})
			return
		}

		writeJSON(w, http.StatusOK, messageResponse{Message: "pong"})
	})
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	payload, err := json.Marshal(value)
	if err != nil {
		// The API only passes fixed response structs, so this cannot occur.
		panic("failed to marshal JSON response: " + err.Error())
	}

	w.Header().Set("Content-Type", jsonContentType)
	w.Header().Set("Content-Length", strconv.Itoa(len(payload)))
	w.WriteHeader(status)
	_, _ = w.Write(payload)
}
"""HTTP routing and response handling for the ping-pong API."""

from dataclasses import dataclass
from http.server import BaseHTTPRequestHandler
from typing import BinaryIO, Optional
from urllib.parse import urlsplit

JSON_CONTENT_TYPE = "application/json; charset=utf-8"
PONG_BODY = '{"message":"pong"}'
NOT_FOUND_BODY = '{"error":"Not Found"}'
METHOD_NOT_ALLOWED_BODY = '{"error":"Method Not Allowed"}'


@dataclass(frozen=True)
class HttpResponse:
    """A JSON response produced by the route matcher."""

    status_code: int
    reason_phrase: str
    body: str
    allow_get: bool = False

    @property
    def content_type(self) -> str:
        return JSON_CONTENT_TYPE

    @property
    def content_length(self) -> int:
        return len(self.body.encode("utf-8"))

    def allow(self) -> Optional[str]:
        return "GET" if self.allow_get else None

    def write_to(self, writer: BinaryIO) -> None:
        """Write this response in HTTP/1.1 wire format."""
        headers = [
            f"HTTP/1.1 {self.status_code} {self.reason_phrase}",
            f"Content-Type: {self.content_type}",
            f"Content-Length: {self.content_length}",
        ]
        if self.allow_get:
            headers.append("Allow: GET")
        headers.extend(("Connection: close", "", ""))

        writer.write("\r\n".join(headers).encode("ascii"))
        writer.write(self.body.encode("utf-8"))
        writer.flush()


def response_for(method: str, target: str) -> HttpResponse:
    """Return the API response for an HTTP method and request target."""
    path = urlsplit(target).path or "/"

    if path == "/ping":
        if method == "GET":
            return HttpResponse(200, "OK", PONG_BODY)

        return HttpResponse(
            405,
            "Method Not Allowed",
            METHOD_NOT_ALLOWED_BODY,
            allow_get=True,
        )

    return HttpResponse(404, "Not Found", NOT_FOUND_BODY)


class PingRequestHandler(BaseHTTPRequestHandler):
    """Adapt ``response_for`` to Python's standard HTTP server."""

    protocol_version = "HTTP/1.1"

    def __getattr__(self, name: str):
        # BaseHTTPRequestHandler looks up do_<METHOD> dynamically. Returning
